"""Кто такая колонка и что она умеет.

Отдельный модуль по той же причине, что остальная логика колонки: разбор
фразы и текст ответов проверяются без колонки, без сети и без модели.

Зачем это. На «кто ты» ответ уходил в языковую модель, и та отвечала:
«Я искусственный интеллект, созданный Alibaba Cloud». Колонка называлась
чужим продуктом и представлялась чужой компанией. Это враньё, причём
самое заметное из всех возможных: первое, что человек проверяет, - это кто
перед ним говорит.

Здесь ответы собираются из того, что колонка действительно умеет. Если
умение выключено или отсутствует, оно не попадает в список. Список
возможностей приходит снаружи: одна и та же правда о колонке не должна
быть написана в двух местах.

Проверки: python3 vendor/irene-va/jane_about.py
"""

import re

# Вопросы о том, кто она.
_WHO = re.compile(
    r"\b(?:кто\s+ты|кто\s+ты\s+такая|кто\s+ты\s+такой|ты\s+кто|"
    r"ты\s+человек|ты\s+робот|ты\s+бот|ты\s+живая|ты\s+искусственный|"
    r"что\s+ты\s+такое|что\s+ты|ты\s+что\s+такое)\b", re.I)
_NAME = re.compile(
    r"\b(?:как\s+тебя\s+зовут|как\s+ты\s+зовёшься|как\s+тебя\s+зовут|"
    r"твоё\s+имя|твое\s+имя|как\s+ты\s+зовёшься|ты\s+как\s+зовёшься)\b",
    re.I)
_CAN = re.compile(
    r"\b(?:что\s+ты\s+умеешь|что\s+ты\s+можешь|на\s+что\s+ты\s+способна|"
    r"что\s+умеешь|чем\s+ты\s+полезна|ты\s+что\s+умеешь|что\s+ты\s+делаешь)\b",
    re.I)
_WHERE = re.compile(
    r"\b(?:где\s+ты|где\s+ты\s+работаешь|на\s+чём\s+ты\s+работаешь|"
    r"на\s+чём\s+работаешь|ты\s+где\s+находишься)\b", re.I)

# Умения. Ключ - что умеет, значение - как это сказать человеку.
# Порядок важен: от самого обычного к неожиданному.
ABILITIES = (
    ("время", "говорю, который час и какое сегодня число"),
    ("будильник", "ставлю будильник на любое время и умею с утра "
                  "включить свет или сказать доброе утро"),
    ("напоминания", "запоминаю, что не забыть, и напоминаю в срок"),
    ("погода", "знаю погоду"),
    ("музыка", "ищу и играю музыку"),
    ("дом", "управляю светом и приборами"),
    ("контекст", "помню, о чём вы говорили, и уточнения не теряю"),
    ("управление", "меняю громкость и повторяю, если не расслышали"),
)


def locative(city):
    """Город в предложном падеже: «в Бресте», «в Гомеле», «в Минске».

    Без этого выходило «я живу в брест» - то есть ровно то враньё, ради
    устранения которого весь этот модуль и писался.
    """
    c = _norm(city)
    if not c:
        return ""
    if c.endswith("ь"):
        return c[:-1] + "е"          # гомель -> гомеле
    if c.endswith(("а", "я")):
        return c[:-1] + "е"          # минска -> минске, никита -> никите
    if c.endswith(("о", "е", "и", "ы", "у")):
        return c + "е"               # москва -> москве, псков -> пскове
    return c + "е"


def _norm(t):
    return " ".join(str(t or "").lower().replace("ё", "е").split())


def abilities_text(abilities=None):
    """Что умеет, из списка включённых умений."""
    have = abilities if abilities is not None else [a for a, _ in ABILITIES]
    words = dict(ABILITIES)
    bits = [words[a] for a in have if a in words]
    if not bits:
        return "Пока почти ничего."
    if len(bits) == 1:
        return "Я %s." % bits[0]
    return "Я %s." % ", ".join(bits[:-1]) + " и %s." % bits[-1]


def answer(phrase, name="Дженет", city=None, abilities=None):
    """Ответ о колонке. None - вопрос не обо мне."""
    p = _norm(phrase)
    if not p:
        return None

    if _NAME.search(p):
        return "Меня зовут %s." % name, "about"

    if _CAN.search(p):
        return abilities_text(abilities), "about"

    if _WHERE.search(p):
        return ("Я работаю на сервере в твоей квартире. Звук идёт через "
                "колонку, а если её нет - через телефон или компьютер.",
                "about")

    if _WHO.search(p):
        loc = (" Я живу в %s." % locative(city).capitalize()) if city else ""
        return ("Я %s - умная колонка. Не человек и не робот: я программа, "
                "которая слышит, считает время и помнит, что ты просил.%s"
                % (name, loc), "about")

    return None


# ---------------------------------------------------------------------------
# Проверки
# ---------------------------------------------------------------------------
def selfcheck():
    fails = []

    def want(cond, msg):
        if not cond:
            fails.append(msg)

    a, src = answer("кто ты") or (None, None)
    want(a and "Дженет" in a, "кто ты: %r" % a)
    want(a and "Alibaba" not in a and "OpenAI" not in a,
         "колонка не должна называть себя чужим продуктом: %r" % a)

    # Это не бот в смысле мессенджера: раньше колонка была Telegram-ботом,
    # и такие ответы звучали особенно нелепо.
    for q in ("ты бот?", "ты человек?", "ты робот?"):
        got = answer(q)
        want(got and got[0] == a, "%s -> %r" % (q, got))

    nm = answer("как тебя зовут")
    want(nm and nm[0] == "Меня зовут Дженет.", "имя: %r" % (nm,))

    can = answer("что ты умеешь")[0]
    want(can and "который час" in can, "что умеешь: %r" % can)
    want(can and "будильник" in can, "будильник не назван: %r" % can)
    want(can.endswith("."), "ответ должен быть полным предложением: %r" % can)

    # Список умений не должен содержать выключенного.
    few = answer("что ты умеешь", abilities=["время", "будильник"])[0]
    want("погоду" not in few and "музыку" not in few,
         "выключенные умения попали в список: %r" % few)

    wh = answer("где ты")
    want(wh and "сервер" in wh[0], "где ты: %r" % (wh,))

    # Город появляется только когда назван.
    want("Гомел" not in answer("кто ты")[0], "город без настройки")
    got = answer("кто ты", city="Гомель")[0]
    want("Гомел" in got, "город должен называться, если он есть: %r" % got)

    # Чужой разговор.
    for q in ("какая сейчас погода", "включи свет", "буди меня в 7 утра",
              "привет"):
        want(answer(q) is None, "лишнее сработало на: %s" % q)

    for f in fails:
        print("FAIL  " + f)
    if not fails:
        print("ok    jane_about: колонка представляется собой, а не Alibaba")
    print("ИТОГ: провалено %d" % len(fails))
    return 1 if fails else 0


if __name__ == "__main__":
    import sys
    sys.exit(selfcheck())